import assert from "node:assert/strict";
import { it } from "node:test";
import { Volume } from "memfs";
import { createFfmpegCommand, evalSyncFfmpeg } from "./index.js";

const nativeAss = `[Script Info]
; Script generated by FFmpeg/Lavc63.1.101
ScriptType: v4.00+
PlayResX: 384
PlayResY: 288
ScaledBorderAndShadow: yes
YCbCr Matrix: None

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Arial,16,&Hffffff,&Hffffff,&H0,&H0,0,0,0,0,100,100,0,0,1,1,0,2,10,10,10,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:01.25,0:00:03.50,Default,,0,0,0,,Hello
Dialogue: 0,0:00:05.00,0:00:06.75,Default,,0,0,0,,there
`;

for (const sync of [false, true]) {
  for (const [start, end, interval] of [
    ["0:00:01.2", "0:00:03.4", "00:00:01,020 --> 00:00:03,040"],
    ["0:00:01.234", "0:00:03.456", "00:00:03,340 --> 00:00:07,560"]
  ]) {
    it(`${sync ? "sync" : "async"} converts ASS centiseconds ${start} to SRT`, async () => {
      const input = nativeAss.slice(0, nativeAss.indexOf("Dialogue:")) +
        `Dialogue: 3,${start},${end},Default,Actor,0010,0020,0030,,Timed\n`;
      const volume = Volume.fromJSON({ "/input.ass": input });
      const args = ["-i", "/input.ass", "/output.srt"];
      if (sync) {
        assert.equal(evalSyncFfmpeg(args, undefined,
          path => volume.existsSync(path) ? volume.readFileSync(path) as Buffer : undefined,
          (path, bytes) => { volume.writeFileSync(path, bytes); return true; }), "");
      } else {
        let stderr = "";
        const result = await createFfmpegCommand().execute({
          args, cwd: "/", env: {}, signal: new AbortController().signal,
          fs: {
            async readFile(path: string) { return volume.readFileSync(path); },
            async writeFile(path: string, bytes: Uint8Array) { volume.writeFileSync(path, bytes); },
            async stat(path: string) { return volume.statSync(path); }
          },
          stdin: (async function* () {})(), stdout: { async write() {} },
          stderr: { async write(bytes: Uint8Array) { stderr += new TextDecoder().decode(bytes); } }
        } as never);
        assert.equal(result.exitCode, 0, stderr);
      }
      assert.equal(volume.readFileSync("/output.srt", "utf8"), `1\n${interval}\nTimed\n\n`);
    });
  }
}
